package com.sakan.iptv;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;

final class PlaybackProbe {
 static final class NotVideo extends IOException {NotVideo(){super("The server returned an error document instead of video");}}
 static String detect(byte[] bytes,int count,String contentType,String url)throws IOException{String text=new String(bytes,0,count,StandardCharsets.UTF_8).replace("\uFEFF","").trim();String lower=text.toLowerCase(Locale.ROOT),type=contentType==null?"":contentType.toLowerCase(Locale.ROOT);if(text.startsWith("#EXTM3U"))return "application/x-mpegURL";if(lower.startsWith("<mpd")||lower.startsWith("<?xml")&&lower.contains("<mpd"))return "application/dash+xml";if(lower.startsWith("<!doctype html")||lower.startsWith("<html")||lower.startsWith("<body")||lower.matches("^[\\[{]\\s*\\\"[a-z_][^\\\"]*\\\"\\s*:.*"))throw new NotVideo();if(count>=8&&bytes[4]=='f'&&bytes[5]=='t'&&bytes[6]=='y'&&bytes[7]=='p')return "video/mp4";if(count>=4&&(bytes[0]&255)==0x1a&&(bytes[1]&255)==0x45&&(bytes[2]&255)==0xdf&&(bytes[3]&255)==0xa3)return "video/x-matroska";if(type.contains("mpegurl"))return "application/x-mpegURL";if(type.contains("dash+xml"))return "application/dash+xml";if(type.contains("text/html")||type.contains("application/json"))throw new NotVideo();return Provider.mime(url);}
 static String inspect(String url,Map<String,String> headers)throws IOException{HttpURLConnection connection=StreamConnection.open(url,headers,0,1024);try(InputStream in=connection.getInputStream()){byte[] prefix=new byte[1024];int count=0;while(count<prefix.length){int n=in.read(prefix,count,prefix.length-count);if(n<0)break;count+=n;}if(count==0)throw new EOFException("Empty media response");return detect(prefix,count,connection.getContentType(),connection.getURL().toString());}finally{connection.disconnect();}}
}
